import runpy,json
from pathlib import Path
S=Path(__file__).resolve().parents[1];e=runpy.run_path(str(S/'work/write_superdaily_early.py'));add=e['add'];out=e['out'];cost=e['cost']
common={'進場方向':'只多／只空／雙向，限制買賣超日訊號的目標方向。','買超均線':'外資買賣超金額含當日的N日算術平均；程式要求索引>=兩邊天數，較首個完整均線再晚一筆才判。','賣超均線':'相同金額序列的另一個N日均值；必須兩側索引都足夠，買側先判成立便不再判空。','買超價格':'單位億；買側平均嚴格>此值為買超，不是商品價格。','賣超價格':'單位億；買側未達且賣側平均嚴格<此值才賣超。','作空部位':'留倉在次交易日首open直接做空；當沖先清多並排待進狀態，首筆HHmm>=作空進場時間才實際空。','作空進場時間':'HHmm達到或超過才執行待空；未要求精確分鐘。當根進空後用else if，下根才可能檢查時刻退出。','作空出場時間':'當沖已進後首筆HHmm>=此時或IsCloseTime判定日收盤，按close平；提早價格／資金停損後仍等狀態機處理。','KBAR間隔ex':'只篩持倉價格／資金風控；買賣超計算、日界調整與當沖排程不需通過。','開始交易時間':'ValidKBAR分鐘相位原點，沒有額外限制次日開盤訊號或當沖排程。'}
entry=['只TX，讀外資每日買賣超金額，日收盤判含當日均值：買側>買門檻優先，否則賣側<賣門檻空，其餘空手。門檻以億換算。','收盤需本根落商品收盤前5分鐘內、下一根越收盤或跨日；訊號於IsSameDate交易日換日的下一根open執行，不必曆日00:00。']
add('外資買賣超','以外資買賣超金額均線判方向，每天加一口至上限；空單可選留倉或指定日內時窗。','籌碼與資金流',entry+['訊號連續同向每日新建一口子項，以目前淨量和最大口數比較；一旦不再同向，下一交易日open一次清原方向，再按新訊號建立。'],['舊倉先依KBAR風控：無移停線時固定損，多open／空high；有線才查直停優先，再回撤；更新線按open換距離、close越新線也退出。所有這些呼叫base退出，所以實際紀錄open，算出的線價未傳入。','當沖空按排程close退；資料末筆close強平。換約使用共用一口平開與偏移後continue，這版未覆寫偏移風控線，價位仍舊約基準。'],[cost,'每子項一口卻全用策略ID1。當沖Status為所有子項共用，foreach第一個可能消耗待空，下一子項同根又可能消耗退出，不能把狀態理解為各子項獨立。'],['當沖短倉每日會新增子項，但退出後沒有逐項移除；共用狀態可能落在較早空子項，遇時窗／收盤可同根對不同子項進／退；若被退出項空手，會清全域Status卻沒有平掉剛進的新空單。','達直停先決條件是已有移停，更新線沒有只朝有利方向限制。缺收盤五分鐘區間就不更新日訊號；缺外資日期回都不是而可能清倉。','相同方向只看已持有淨量，並未把所有待進排程加總；最大口數不是一次固定下滿。'],common|{'最大口數':'每日同向只增一口，到當時已持有淨量上限才停增；待進當沖未算。','停損比':'每子項進場價加減%或點數固定線，多open／空high判，實際open成交。','啟動移停比':'入場價加減距離啟動high/low判，啟動後改當根open為後續基準。','移停拉回比':'每次以當根open加減%或點數換線，只判新舊不同，close可當根觸發，成交仍open。','直接停利比':'入場價加減距離；必須已有移停線才檢查，並非啟動前也生效。'})
stop={'月停損':'使用且換算後門檻>0才查；月基準其實在換約事件重設，封鎖至下一換約。','當月最大損失':'按換約下一根open換%或點數；首段私有值未設定，0不使用。','周停損':'使用且門檻>0時檢查相對周基準損益，達損封鎖至下一指定星期交易日首。','當周最大損失':'指定周W交易日首open換%或點數；首段尚未該重設點就未初始化此門檻。','周W開始計算':'DayOfWeek整數0週日、1週一至6週六；在交易日切換時若下一根星期相符才重設，缺該交易日不自動順延。','日停損':'使用且門檻>0時檢查從前日收盤設基準的損益，封鎖到下一收盤重設。','當日最大損失':'日收盤按下一根open換%或點數，基準=(當根close+delta)×持倉+未實現項+FIFO累計實現；0不檢查。'}
add('外資買賣超_日停損','買賣超均線決定單一口方向，改以日／周／換約期累積損失封鎖，空單可留倉或當沖。','籌碼與資金流',entry+['只有一個±1子項，方向不變不每天加碼；交易日切換先參考封鎖旗標，允許時於下一根open建新方向或反手。'],['持倉且通過KBAR才計open×部位+未實現項+FIFO累計實現，依日→周→月基準差檢查，達各正門檻便open平並設相應旗標。','日收盤重設日旗與基準；指定周W交易日首重設周旗並於方向調整後記周基準；換約平close再重設月旗／基準。','當沖空按指定時間或日收盤close平，換約與資料末筆也按close退出並continue。'],[cost,'日／周／月門檻為價格點數，百分比在各重設點換算；不是貨幣資金百分比，也不是每筆進場固定價差停損。','資金損益檢查只在有倉時進行；相同一筆profit可同時使多個旗標成立。'],['待當沖進場的狀態機不檢查損失旗標，因此已排定空單仍可能在停損檢查之後進場；不能說封鎖涵蓋所有路徑。','周W缺當日資料不順延重設；月不是曆月1日。私有門檻Clear未重設，首段與重用物件均需留意。','本類別獨立實作，沒有一般版最大口數或固定／移動停利；名稱雖日停損，仍可同時啟用周與月損失限制。'],common|stop)
(S/'analysis/SuperDaily.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print('Wrote Daily foreign flow pair')
